CREATE TABLE IF NOT EXISTS `user_login_events` (
  `id` int AUTO_INCREMENT PRIMARY KEY,
  `user_id` int NOT NULL,
  `ip_address` varchar(64),
  `user_agent` text,
  `country` varchar(64),
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS `user_page_view_events` (
  `id` int AUTO_INCREMENT PRIMARY KEY,
  `user_id` int,
  `session_id` varchar(64),
  `path` varchar(512) NOT NULL,
  `referrer` varchar(512),
  `duration_ms` int,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS `lms_video_events` (
  `id` int AUTO_INCREMENT PRIMARY KEY,
  `user_id` int NOT NULL,
  `lesson_id` int NOT NULL,
  `course_id` int NOT NULL,
  `event_type` varchar(32) NOT NULL,
  `position_sec` int NOT NULL DEFAULT 0,
  `duration_sec` int NOT NULL DEFAULT 0,
  `percent_watched` int NOT NULL DEFAULT 0,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE IF NOT EXISTS `lms_quiz_attempts` (
  `id` int AUTO_INCREMENT PRIMARY KEY,
  `user_id` int NOT NULL,
  `lesson_id` int NOT NULL,
  `course_id` int NOT NULL,
  `score` int NOT NULL,
  `passed` boolean NOT NULL,
  `total_questions` int NOT NULL,
  `correct_answers` int NOT NULL,
  `time_taken_sec` int,
  `answers_json` longtext,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS `idx_ule_user` ON `user_login_events` (`user_id`);
CREATE INDEX IF NOT EXISTS `idx_ule_created` ON `user_login_events` (`created_at`);
CREATE INDEX IF NOT EXISTS `idx_upve_user` ON `user_page_view_events` (`user_id`);
CREATE INDEX IF NOT EXISTS `idx_upve_path` ON `user_page_view_events` (`path`(255));
CREATE INDEX IF NOT EXISTS `idx_upve_created` ON `user_page_view_events` (`created_at`);
CREATE INDEX IF NOT EXISTS `idx_lve_user` ON `lms_video_events` (`user_id`);
CREATE INDEX IF NOT EXISTS `idx_lve_lesson` ON `lms_video_events` (`lesson_id`);
CREATE INDEX IF NOT EXISTS `idx_lve_created` ON `lms_video_events` (`created_at`);
CREATE INDEX IF NOT EXISTS `idx_lqa_user` ON `lms_quiz_attempts` (`user_id`);
CREATE INDEX IF NOT EXISTS `idx_lqa_lesson` ON `lms_quiz_attempts` (`lesson_id`);
CREATE INDEX IF NOT EXISTS `idx_lqa_created` ON `lms_quiz_attempts` (`created_at`);

